import cadquery as cq

PARAMETERS = {"name":"COMPACT_BSPLINE_RULED_LOFT","sections":[{"z":-0.4326795,"points":[[0.0324341,0.2570195],[0.0103573,0.2693133],[-0.0046971,0.2378766],[-0.0079482,0.210094],[-0.0029697,0.1835412],[0.0205129,0.1845082],[0.0313123,0.2198787],[0.0334846,0.2477573]]},{"z":-0.3389727,"points":[[0.0345005,0.2536478],[-0.0234602,0.1475346],[-0.0381816,-0.0524725],[-0.0237637,-0.2019251],[0.0440227,-0.2930851],[0.0154339,-0.1462654],[0.0171003,0.053936],[0.0309798,0.2037378]]},{"z":-0.245266,"points":[[0.0325691,0.2441066],[-0.0234177,0.14355],[-0.0375605,-0.0475803],[-0.0236239,-0.1903346],[0.0408011,-0.2782291],[0.015288,-0.1379845],[0.0155673,0.0532745],[0.0291875,0.1963859]]},{"z":-0.1515592,"points":[[0.0309773,0.2346536],[-0.0228731,0.1395002],[-0.0364011,-0.0428047],[-0.0227639,-0.1789413],[0.0386029,-0.2635249],[0.0143707,-0.1299678],[0.0155053,0.0525648],[0.0278191,0.189154]]},{"z":-0.0578525,"points":[[0.0299677,0.2253518],[-0.0219706,0.1360676],[-0.0350346,-0.0373257],[-0.0218428,-0.166842],[0.0354502,-0.2482863],[0.0146687,-0.1212854],[0.0156244,0.0521664],[0.0267364,0.1821135]]},{"z":0.0358543,"points":[[0.0286099,0.2157732],[-0.0212359,0.1315988],[-0.0335856,-0.0326172],[-0.0213012,-0.1553084],[0.0341799,-0.2324346],[0.0135699,-0.112469],[0.0145584,0.0518388],[0.0254076,0.1748936]]},{"z":0.1295611,"points":[[0.0271754,0.2037338],[-0.0196775,0.1292161],[-0.0322129,-0.0259761],[-0.0210961,-0.1419106],[0.030452,-0.2198012],[0.012954,-0.1067674],[0.0133486,0.0486401],[0.0238536,0.1650102]]},{"z":0.2232678,"points":[[0.0251389,0.1960966],[-0.0191699,0.1219446],[-0.0311297,-0.0240045],[-0.0201912,-0.1330843],[0.0299365,-0.2023473],[0.0126157,-0.0957371],[0.0122285,0.0503766],[0.0226226,0.1597556]]},{"z":0.3169746,"points":[[0.0321858,0.1857786],[-0.0156815,0.1215652],[-0.0291919,-0.0160815],[-0.0197439,-0.1192356],[0.028151,-0.1896375],[0.0124732,-0.0887274],[0.0118878,0.049267],[0.0250264,0.1521592]]},{"z":0.4106813,"points":[[0.0300335,0.1781179],[-0.0143512,0.1152943],[-0.028282,-0.0124328],[-0.0182607,-0.1082662],[0.0258985,-0.1707247],[0.0121213,-0.0771496],[0.0122852,0.0511549],[0.0254683,0.1466759]]},{"z":0.5043881,"points":[[0.0075032,0.0431802],[-0.0177079,0.0355011],[-0.0230434,-0.0179796],[-0.0203515,-0.0583147],[-0.0044581,-0.0949906],[0.0111866,-0.0643223],[0.0102546,-0.0105888],[0.0089637,0.029832]]}],"origin":[0.4735657,-0.349081,0.0953289],"xdir":[0.0284395,-0.2496768,-0.9679115],"normal":[0.9912529,-0.1177968,0.0595115],"section_count":11,"points_per_section":8,"section_selection":"uniform endpoints included","point_selection":"uniform cyclic samples","section_curve":"open B-spline + explicit closure","loft_ruled":true}

def build_model():
    p=PARAMETERS; wires=[]
    for sec in p["sections"]:
        plane=cq.Plane(origin=tuple(p["origin"][i]+p["normal"][i]*sec["z"] for i in range(3)), xDir=tuple(p["xdir"]), normal=tuple(p["normal"]))
        wires.append(cq.Workplane(plane).spline([tuple(x) for x in sec["points"]], periodic=False).close().val())
    return cq.Solid.makeLoft(wires, True)

if __name__ == "__main__":
    out=Path(__file__).resolve().parent; t=time.time(); shape=build_model(); valid=bool(shape.isValid())
    cq.exporters.export(shape,str(out/"reconstructed.step")); cq.exporters.export(shape,str(out/"reconstructed.stl"))
    b=shape.BoundingBox(); (out/"geometry.json").write_text(json.dumps(dict(valid=valid,solids=len(shape.Solids()),faces=len(shape.Faces()),bbox=[b.xmin,b.ymin,b.zmin,b.xmax,b.ymax,b.zmax],build_seconds=time.time()-t),indent=2))
    print("VALIDATED",valid,"SOLIDS",len(shape.Solids()),"FACES",len(shape.Faces()),flush=True)
